starter.java:
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = in.nextInt();
        }
        int mn = 0;
        int mx = 0;
        for (int x : a) {
            if (x < mn) {
                mn = x;
            }
            if (x > mx) {
                mx = x;
            }
        }
        System.out.println(mn + mx);
    }
}

